from __future__ import annotations

from typing import Any

from workpeg.ui.state import State
from workpeg.ui.widgets import BaseWidget


class App:
    """Base class for compiler-based Peg apps.

    Subclass this, declare State fields at class level,
    implement methods, and define build() to return a widget tree.
    The compiler parses subclasses and generates JavaScript.
    """

    def build(self) -> BaseWidget:
        raise NotImplementedError


class Component:
    """Base class for reusable components (Flutter-inspired).

    Subclass, declare props as ``__init__`` parameters, optionally add ``State``
    fields for own state, and implement ``build()``.  Embed instances in another
    component's or page's ``build()`` like a widget::

        class PageHeader(Component):
            def __init__(self, title):
                self.title = title

            def build(self):
                return Column(Text(self.title), Link("← Home", href="/"))

        class CounterPage(App):
            def build(self):
                return Column(PageHeader(title="Counter"), Text("…"))

    Inside a component, ``self.<param>`` reads a prop and ``self.<field>`` reads
    own ``State``.  A component that declares ``State`` is *stateful*: each
    embedded instance keeps its own state across re-renders, like a Flutter
    StatefulWidget; one without is *stateless*.
    """

    def build(self) -> BaseWidget:
        raise NotImplementedError


class _Location:
    """Browser ``window.location`` proxy for use in ``build()`` f-strings.

    Import ``location`` from ``workpeg.ui`` and reference its attributes
    inside an f-string.  The compiler maps each ``location.<prop>`` expression
    to ``window.location.<prop>`` in the generated JavaScript — the value is
    read from the live browser URL at render time.

    Example::

        from workpeg.ui import App, Column, Text, Link, location

        class NotFoundPage(App):
            def build(self):
                return Column(
                    Text(f"{location.pathname} not found"),
                    Link("← Home", href="/"),
                )

    Supported properties: ``pathname``, ``href``, ``search``, ``hash``,
    ``hostname``, ``origin``.  Any ``location.<attr>`` is accepted — the
    compiler passes the attribute name through verbatim.
    """

    pathname: str = ""
    href: str = ""
    search: str = ""
    hash: str = ""
    hostname: str = ""
    origin: str = ""


#: Sentinel for ``window.location`` — use in ``build()`` f-strings only.
location = _Location()


class _Route:
    """Dynamic route-param proxy for use in ``build()``.

    Routes may carry ``[name]`` segments, e.g. ``Route("/states/[state_id]/cities",
    Cities)``.  Inside the page, read the captured value as ``route.<name>`` —
    the compiler maps it to the segment matched from the live URL.  Values are
    always strings (URL segments).

    Example::

        from workpeg.ui import App, Column, Text, route

        class Cities(App):
            def build(self):
                return Column(Text(f"Cities in state {route.state_id}"))

    Any ``route.<attr>`` is accepted — the param name is passed through verbatim,
    so a name with no matching segment simply reads as "".
    """

    def __getattr__(self, name: str) -> str:
        return ""


#: Sentinel for dynamic route params — use ``route.<name>`` in ``build()``.
route = _Route()


class _Query:
    """URL query-string proxy for use in ``build()``.

    Read a ``?key=value`` parameter from the live URL as ``query.<key>`` — the
    compiler maps it to the value parsed from ``window.location.search``. Values
    are always strings; a missing key reads as "".

    Example::

        from workpeg.ui import App, Column, Text, query

        class Search(App):
            def build(self):
                return Column(Text(f"Results for {query.q}"))   # /search?q=…
    """

    def __getattr__(self, name: str) -> str:
        return ""


#: Sentinel for URL query params — use ``query.<key>`` in ``build()``.
query = _Query()


class _Clock:
    """The current date and time, read at render time.

    Import ``clock`` from ``workpeg.ui``. Its properties give the *current*
    moment as the page renders — use them in ``build()`` (typically inside a
    ``Text`` f-string). For a ticking display, pair it with ``set_interval`` so
    the page re-renders on a schedule::

        from workpeg.ui import App, State, Column, Text, clock, set_interval

        class Now(App):
            tick = State(0)

            def on_mount(self):
                set_interval(self.beat, 1000)

            def beat(self):
                self.tick += 1                      # forces a re-render

            def build(self):
                return Column(Text(f"{clock.time} · {clock.date}"))

    Properties (the current value at render time): ``year``, ``month`` (1–12),
    ``day`` (1–31), ``hour`` (0–23), ``minute``, ``second``, ``weekday``
    ("Monday"), ``month_name`` ("June"), ``date`` (locale date), ``time``
    (locale time), ``datetime`` (locale date + time), ``iso`` (ISO-8601).

    Methods work with epoch-millisecond timestamps (plain integers), so a moment
    can be captured in ``State`` and formatted later:

    * ``clock.now()`` — the current time as an epoch-ms integer (store this).
    * ``clock.format(ts)`` — a locale date + time string for ``ts``.
    * ``clock.format(ts, style)`` — ``style`` is ``"date"``, ``"time"``,
      ``"datetime"`` (the default), ``"iso"``, or ``"relative"`` ("5 minutes
      ago").

    Everything compiles to small runtime helpers backed by the browser's
    ``Date`` / ``Intl`` APIs; the sentinel is never executed in Python.
    """

    year: int = 0
    month: int = 0
    day: int = 0
    hour: int = 0
    minute: int = 0
    second: int = 0
    weekday: str = ""
    month_name: str = ""
    date: str = ""
    time: str = ""
    datetime: str = ""
    iso: str = ""

    def now(self) -> int:
        """The current time as epoch milliseconds (a plain integer)."""
        return 0

    def format(self, timestamp: int, style: str = "datetime") -> str:
        """Format an epoch-ms ``timestamp`` — see the class docstring."""
        return ""


#: Sentinel for the current date/time — use ``clock.*`` in ``build()``.
clock = _Clock()


class _Fullscreen:
    """Real browser fullscreen — the Fullscreen API, like pressing F on a video.

    Call the toggles from an event handler (they need a user gesture)::

        def on_mount(self):
            on_shortcut("f", self.go_fs, modifier=False)   # F toggles it

        def go_fs(self):
            fullscreen.toggle()

    ``fullscreen.toggle()`` / ``enter()`` / ``exit()`` drive the **document** in
    and out of OS fullscreen (the document element, so it survives re-renders —
    an app/outlet element would be rebuilt by its shell and drop fullscreen).
    ``fullscreen.active()`` — read in ``build()`` — is ``True`` while fullscreen,
    so the UI can react (e.g. show an exit button); the page re-renders whenever
    fullscreen changes, including the user pressing Esc. Compiled to
    ``Workpeg.fullscreen*``; a no-op in plain Python.
    """

    def toggle(self) -> None:
        ...

    def enter(self) -> None:
        ...

    def exit(self) -> None:
        ...

    def active(self) -> bool:
        ...


#: Sentinel for real browser fullscreen — use ``fullscreen.*`` in handlers.
fullscreen = _Fullscreen()


class Store:
    """A global, app-wide reactive store shared across every page.

    Declare it **once** as a class attribute on your :class:`Router` (or a single
    :class:`App`), with the initial fields as keywords::

        class MyApp(Router):
            store = Store(count=0, items=[])
            routes = [Route("/", Home), Route("/cart", Cart)]

    Then read and write it from any page via the ``store`` sentinel — its value
    survives navigation, unlike per-page ``State``::

        from workpeg.ui import store

        class Cart(App):
            def add(self):
                store.count += 1          # re-renders the current page
            def build(self):
                return Text(f"{store.count} in cart")
    """

    def __init__(self, **defaults: Any):
        self.defaults = defaults


class _Store:
    """Access proxy for the global store — ``store.<field>`` in build()/methods.
    The value is the live store field; assignments re-render the current page."""

    def __getattr__(self, name: str) -> Any:
        return ""


#: Sentinel for the global store — ``store.<field>`` reads and writes it.
store = _Store()


class Translations:
    """The Peg's message catalogue, for the :class:`~workpeg.ui.Locale` widget.

    Declare it **once** as a class attribute on your :class:`Router` (or a single
    :class:`App`). Each keyword is a language — a two-letter code, optionally with
    a region (``en``, ``pt_BR``) — mapping token names to the translated text::

        class MyApp(Router):
            translations = Translations(
                en={"greeting": "Hello, {name}", "items": "{count} items"},
                fr={"greeting": "Bonjour, {name}", "items": "{count} articles"},
                default="en",
            )
            routes = [...]

    Then render a message with :class:`~workpeg.ui.Locale`::

        Locale("greeting", values={"name": self.name})

    The active language follows the user's workspace choice (the language picker
    in Settings, shared through ``localStorage``), falling back to the browser's
    language and then to ``default``. **If the chosen language is not one you
    supplied, your `default` is used** — you only translate the languages you
    choose to support. Switching the language re-renders every ``Locale`` widget
    in place, with no reload.

    Messages are inserted with ``textContent``, never as markup, so a catalogue
    entry can never inject HTML.
    """

    def __init__(self, *, default: str = "", **languages: "dict[str, str]"):
        # `default` is the language used when the active one isn't in the
        # catalogue; if omitted, the first language declared is the default.
        self.default = default
        self.languages = languages


class Theme:
    """Override pegment's design tokens for the whole Peg.

    Declare it **once** as a class attribute on your :class:`Router` (or a single
    :class:`App`); each keyword overrides the matching **Pegment** token on
    ``:root``, re-theming every widget at once. No CSS is injected — only the
    design system's own token values are set::

        class MyApp(Router):
            theme = Theme(primary="#0a7a4f", radius="12px", font="Georgia, serif")
            routes = [...]

    Token keywords map to Pegment custom properties: ``primary`` →
    ``--color-brand-primary``, ``primary_fg`` → ``--color-brand-on-primary``,
    ``fg`` → ``--color-text-primary``, ``muted`` → ``--color-text-secondary``,
    ``page`` → ``--color-bg-canvas``, ``bg`` / ``surface`` / ``sidebar`` →
    ``--color-surface-default``, ``border`` → ``--color-border-subtle``,
    ``radius`` → ``--radius``, ``gap`` → ``--space-sm``, ``font`` →
    ``--font-base``, ``transition`` → ``--transition``. Values are CSS strings
    (``"#0a7a4f"``, ``"12px"``, ``"Georgia, serif"``). For light/dark, prefer
    :func:`set_color_scheme` (Pegment's built-in palettes).
    """

    def __init__(self, **tokens: str):
        self.tokens = tokens


class SearchManifest:
    """Declare how this Peg's rows present in Workpeg's universal search.

    A Peg owns its search representation: the **label** a hit reads as, the
    **link** it opens, and the **icon** beside it. Declare it **once** as a
    class attribute on your :class:`Router` (or a single :class:`App`), the
    same place :class:`Theme` and ``fonts`` live::

        class Invoices(Router):
            search_manifest = SearchManifest(
                label="{needle} in {table.name}: {haystack}",
                link="{domain}/b/{business}/invoice/{row}",
                icon="cash",
            )
            routes = [...]

    All three are optional — omit one and Workpeg fills that field from its
    default (``{haystack} · {table.name}`` /
    ``{workspace}/tables/{table}`` / ``table``), so
    ``SearchManifest(icon="cash")`` re-icons and keeps the default label and
    link. Declaring nothing at all leaves the whole default in place — this is
    for Pegs that want their own voice.

    **Templates** interpolate a fixed variable set (an unknown ``{var}`` is
    left verbatim rather than erroring):

    ==================  ====================================================
    ``{needle}``        the search query
    ``{haystack}``      a short snippet of the matched row's first text
    ``{table.name}``    the table's display name
    ``{table}``         the table's id
    ``{row}``           the row's id
    ``{business}``      the business id
    ``{peg}``           this Peg's name
    ``{namespace}``     the table's namespace
    ``{domain}``        this Peg's app origin (``https://<peg>.workpeg.com``)
    ==================  ====================================================

    **The link is validated at build time.** A hit's href is only ever a
    relative path (``/…``) or an ``https`` URL on the platform domain (that is
    what ``{domain}`` expands to) — a ``javascript:``/``data:`` scheme, a
    ``//host``, or an off-platform ``https://`` is a compile error, because a
    search result must never run script or send a searcher off-site. The
    server enforces the identical rule when it renders, so the two can't drift.

    ``build_ui`` writes the declaration to ``dist/manifest.json``; ``workpeg
    cdn submit`` ships it to the Peg's namespace, where the platform ingests
    and renders it (see docs/routing.md — *A Peg's search representation*).
    """

    #: The keys a manifest may declare — mirrors the server's MANIFEST_KEYS.
    KEYS = ("label", "link", "icon")

    def __init__(self, *, label: "str | None" = None,
                 link: "str | None" = None, icon: "str | None" = None):
        self.label = label
        self.link = link
        self.icon = icon


def set_interval(callback: Any, milliseconds: int) -> None:
    """Run ``callback`` (a ``self.<method>`` reference) every ``milliseconds``.

    Use it in ``on_mount`` to drive time-based updates (a clock, polling). The
    interval is tied to the page and cleared automatically when you navigate
    away. Compiled to ``Workpeg.setInterval``; a no-op when run in plain Python.
    """


def set_timeout(callback: Any, milliseconds: int) -> None:
    """Run ``callback`` (a ``self.<method>`` reference) once after
    ``milliseconds``. Compiled to ``Workpeg.setTimeout``; cleared on navigation
    like :func:`set_interval`."""


def set_theme(theme: "Theme") -> None:
    """Re-theme the design system at runtime — call it from a handler to switch
    themes live (a dark-mode toggle, say)::

        class Page(App):
            dark = State(False)

            def toggle(self):
                self.dark = not self.dark
                if self.dark:
                    set_theme(Theme(page="#0b0b0c", fg="#f4f4f5",
                                    surface="#15171b", primary="#ccff00"))
                else:
                    set_theme(Theme(page="#eef1f7", fg="#1b2333",
                                    surface="#ffffff", primary="#0a7a4f"))

    It swaps the active Pegment tokens on ``:root`` **app-wide** (the switch
    survives navigation), so pass a *complete* :class:`Theme` — the previous
    theme's overrides are cleared first. The argument is an inline ``Theme(...)``.
    Compiled to ``Workpeg.applyTheme``; a no-op in plain Python.

    For plain light/dark switching, prefer :func:`set_color_scheme` — it uses
    Pegment's built-in light/dark palettes instead of hand-picked colours.
    """


def set_color_scheme(mode: str) -> None:
    """Switch the light/dark colour scheme — ``set_color_scheme("dark")``,
    ``"light"``, or ``"system"``.

    Pegment ships full light **and** dark token palettes; this flips between them
    by toggling the ``.dark`` / ``.light`` class on ``<html>`` (``"system"``
    removes both, so the OS ``prefers-color-scheme`` decides). It's the clean way
    to do a dark-mode toggle — no colours to hand-pick::

        class Page(App):
            def to_dark(self): set_color_scheme("dark")
            def to_light(self): set_color_scheme("light")
            def to_system(self): set_color_scheme("system")

    The class lives on ``<html>``, so the choice survives navigation. Compiled to
    ``Workpeg.setColorScheme``; a no-op in plain Python.
    """


def toggle_sidebar() -> None:
    """Collapse or expand the :class:`~workpeg.ui.Scaffold` sidebar.

    The Scaffold's own toggle button calls this; you rarely call it directly.
    Unlike a store write, it doesn't re-render — it flips the ``.pg-collapsed``
    class on ``<html>`` (like :func:`set_color_scheme`), and the sidebar drives
    its width and label visibility off ``:root`` custom properties, so the
    collapse *animates* rather than snapping. The class lives on ``<html>``, so
    the collapsed state survives an SPA navigation. Compiled to
    ``Workpeg.toggleSidebar``; a no-op in plain Python.
    """


def toggle_incognito() -> None:
    """Enter or leave **incognito chat** mode on the reserved Workpeg AI route.

    The Scaffold's own spy button calls this; you rarely call it directly.
    Like :func:`toggle_sidebar` it doesn't re-render — it flips the
    ``.wpai-incognito`` class on ``<html>`` and the AI surface (ai.js) keys its
    whole incognito UX off that class: the private greeting, the dashed
    composer, the hidden history/suggestions, and creating the next chat as
    ``incognito`` (hidden from history, deleted lazily server-side). Compiled
    to ``Workpeg.toggleIncognito``; a no-op in plain Python.
    """


def toggle_ai_history() -> None:
    """Open (or close) the **chat-history drawer** on the reserved Workpeg AI
    route.

    The Scaffold's own top-bar history button calls this on an open
    conversation; you rarely call it directly. It reaches into the AI surface
    (ai.js) to slide its history drawer in from the right — the same drawer the
    ``/new`` composer offers from its nav title. A no-op when the AI surface
    isn't mounted. Compiled to ``Workpeg.toggleAIHistory``; a no-op in plain
    Python.
    """


def set_title(text: str) -> None:
    """Set the browser tab's document ``<title>`` at runtime — typically from
    ``on_mount`` (and the methods that change what it shows), so the tab can
    reflect state or a route param::

        class Inbox(App):
            unread = State(12)

            def on_mount(self):
                set_title(f"Inbox ({self.unread})")   # initial, from state

            def mark_read(self):
                self.unread = max(self.unread - 1, 0)
                set_title(f"Inbox ({self.unread})")   # re-apply on change

    The argument is a string (an f-string may interpolate ``self.<state>`` or
    ``route.<param>``); only that inert text reaches ``document.title`` — never
    markup or code. It isn't reactive on its own: restate it after changing the
    state it depends on. For a fixed title, prefer the declarative class
    attribute ``title = "..."``. Compiled to ``Workpeg.setTitle``; a no-op in
    plain Python.
    """


def toast(message: str, kind: str = "info") -> None:
    """Show a transient notification — a small message that slides in at the
    corner and dismisses itself. Fire-and-forget: call it from any method (after
    a save, on an error)::

        def save(self):
            ...
            toast("Saved", kind="success")

        def fail(self):
            toast(f"Couldn't reach {self.host}", kind="danger")

    ``message`` is a string (an f-string may interpolate state). ``kind`` is one
    of ``"info"`` (default), ``"success"``, ``"warning"``, ``"danger"`` and just
    picks the colour. Compiled to ``Workpeg.toast``; a no-op in plain Python.
    """


def copy(text: str) -> None:
    """Copy ``text`` to the system clipboard — call it from a click handler (the
    clipboard needs a user gesture), then confirm with a toast::

        def copy_link(self):
            copy(self.url)
            toast("Link copied", kind="success")

    ``text`` is a string (an f-string may interpolate state). Fire-and-forget and
    best-effort (it falls back to a hidden textarea on older browsers). Compiled
    to ``Workpeg.copy``; a no-op in plain Python.
    """


def on_color_scheme_change(callback: Any) -> None:
    """Run ``callback`` (a ``self.<method>`` reference) whenever the computer's
    colour-scheme preference flips — so a "System" theme can follow the OS live::

        class Page(App):
            mode = State("light")

            def on_mount(self):
                on_color_scheme_change(self.os_changed)

            def os_changed(self):
                if self.mode == "system":
                    self.use_system()      # re-apply based on color_scheme()

    Register it in ``on_mount``. The watcher is tied to the page and removed
    automatically when you navigate away. Compiled to ``Workpeg.onColorScheme``;
    a no-op in plain Python. See :func:`color_scheme`.
    """


def on_table_change(callback: Any, *, table: Any = None) -> None:
    """Run ``callback`` (a ``self.<method>`` reference) when a table this page
    can read changes, or a row in one does, so the page can fetch again::

        class Orders(App):
            rows = State([])

            async def on_mount(self):
                on_table_change(self.changed)          # every table of this peg
                await self.reload()

            async def changed(self, event):
                await self.reload()                    # whatever the kind

            async def reload(self):
                self.rows = await workpeg.get_rows(ORDERS, limit=100)

    The method gets ``{"kind": ..., "table": ...}``. ``kind`` is ``"rows"``
    (a row of ``table`` was added, changed or removed), ``"table"`` (that
    table's name, columns or sharing changed; ``table`` is ``""`` when the
    list of tables changed) or ``"resync"`` (changes may have been missed;
    fetch everything again). The event never carries data: fetch it with
    ``workpeg.get_rows``, under the same permissions as any read.

    Pass ``table=`` (a uuid, a module constant, State or a route param) to
    hear one table only. Register it in ``on_mount`` of a page or a shell;
    it is removed when the page goes. A page must still work if no event
    ever comes. Compiled to ``Workpeg.onTableChange``; a no-op in plain
    Python. See ``docs/data-realtime.md``.
    """


def on_shortcut(key: str, callback: Any, *, modifier: bool = True) -> None:
    """Run ``callback`` (a ``self.<method>`` reference) on a keyboard shortcut.

    By default it's a **Cmd/Ctrl + key** combo — ``⌘`` on macOS, ``Ctrl``
    elsewhere, automatically::

        class AppShell(Shell):
            open = State(True)

            def on_mount(self):
                on_shortcut("\\\\", self.toggle)     # ⌘\\ / Ctrl\\

            def toggle(self):
                self.open = not self.open

    Pass ``modifier=False`` for a **plain key** (no Cmd/Ctrl) — e.g. ``f`` to
    toggle a fullscreen view. A plain-key shortcut is ignored while the user is
    typing in a form field (input / textarea / select / contenteditable) so it
    never hijacks a keystroke::

        on_shortcut("f", self.toggle_fullscreen, modifier=False)

    ``key`` is a single character. Register it in ``on_mount``; the listener is
    tied to the page and removed on navigation. Compiled to
    ``Workpeg.onShortcut``; a no-op in plain Python. See :func:`platform`.
    """


def color_scheme() -> str:
    """The computer's colour-scheme preference — ``"dark"`` or ``"light"``
    (the CSS ``prefers-color-scheme``), read at render time. Use it to follow
    the OS theme::

        if color_scheme() == "dark":
            set_theme(Theme(page="#0b0b0c", fg="#f4f4f5"))
        else:
            set_theme(Theme(page="#eef1f7", fg="#1b2333"))

    Works anywhere an expression does — a condition, or an f-string
    (``Text(f"System is {color_scheme()}")``). Compiled to
    ``Workpeg.colorScheme()``; a no-op returning ``"light"`` in plain Python.
    """
    return "light"


def platform() -> str:
    """The operating-system family — ``"mac"``, ``"windows"``, ``"linux"`` or
    ``"other"`` — read at render time. Use it to show the right modifier key,
    say::

        Text(f"{'⌘' if platform() == 'mac' else 'Ctrl'}+\\\\ to toggle")

    Works anywhere an expression does. Compiled to ``Workpeg.platform()``;
    a no-op returning ``"other"`` in plain Python. See :func:`on_shortcut`.
    """
    return "other"


def biz_url(path: str) -> str:
    """The current business-scoped href — ``"/b/<business_id>" + path`` — with
    the active business read from the URL at render time. Build nav/link
    destinations with it instead of hand-writing the ``/b/<id>`` prefix::

        NavItem("Kanban", biz_url("/kanban"))   # → /b/<business_id>/kanban
        Link("Home", href=biz_url("/"))

    Works anywhere an expression does (a prop, an f-string). Compiled to
    ``Workpeg.bizUrl(path)``; in plain Python it just returns *path*.
    """
    return path


class _Http:
    """Sentinel for browser requests, used inside ``async def`` methods.

    ``http.get(url)`` and ``http.post(url, data)`` compile to the runtime's
    fetch helpers and resolve to parsed JSON. They exist so source stays valid
    Python; they are never executed in Python (the app runs as JavaScript).

    ``http.post_file(url, file, field, fields)`` submits ``multipart/form-data``
    — the one shape ``post`` cannot express, because it serialises its body with
    ``JSON.stringify``. *file* is a :class:`FileUpload` selection dict or its
    ``url`` string; the dict also carries the filename, which the string does
    not, so pass the dict when the server cares what the file is called.

    A non-2xx rejects, and the caught error carries two things::

        except Exception as failure:
            failure.message   # prose for a person: "HTTP 403 Forbidden: …"
            failure.problem   # the problem details `type` slug, for a program

    Branch on ``failure.problem`` — the last path segment of an RFC 9457
    ``type`` URL, e.g. ``"mfa-enrolment-required"``. It is always a string
    (``""`` when the refusal named no type, when the body was not JSON, or
    when the request never arrived), so a comparison never meets ``None``.
    ``failure.message`` is prose that gets translated and rewritten, which is
    why matching on it is not a contract.
    """

    def _unavailable(self, method: str) -> Any:
        raise NotImplementedError(
            f"http.{method} is compiled to a browser request; await it in "
            "an async method"
        )

    def get(self, url: str) -> Any:
        return self._unavailable("get")

    def post(self, url: str, data: Any = None) -> Any:
        return self._unavailable("post")

