http = _Http()


class _Sso:
    """Sentinel for Sign in with Workpeg, used inside ``async def`` methods.

    ``await sso.approve(request_id)`` shows the consent screen for a sign-in your
    application has already parked with the platform, and resolves with what the person
    approved — a mapping carrying ``code`` and ``state`` — or ``None`` if they closed
    it without choosing.

    The screen itself is drawn by the SDK's chrome, not by your app: which businesses
    are offered, what each would grant, and what is sent to approve are not yours to
    restyle. What resolves is an authorization code bound to the PKCE verifier your
    *server* holds, so it is worthless to the page and meant to go straight back.
    """

