#: Sentinel for the authenticated user (the ``/v1/users/me/`` payload). Populated
#: by an :class:`~workpeg.ui.widgets.Authenticated` gate; read ``user.<field>``.
user = _User()


class Route:
    """Maps a URL path to an :class:`App` subclass.

    Used inside a :class:`Router` declaration::

        class MyApp(Router):
            routes = [
                Route("/", HomePage),
                Route("/about", AboutPage),
            ]
    """

    def __init__(self, path: str, app: type) -> None:
        self.path = path
        self.app = app


class Router:
    """Base class for multi-route Peg apps.

    Declare a ``routes`` class variable containing a list of :class:`Route`
    objects. The compiler generates a History-API-based SPA that switches
    between pages without a full-page reload.

    Example::

        class Home(App):
            def build(self):
                return Column(Text("Home"), Link("About", href="/about"))

        class About(App):
            def build(self):
                return Column(Text("About Us"), Link("Home", href="/"))

        class MyApp(Router):
            routes = [
                Route("/", Home),
                Route("/about", About),
            ]
    """

    routes: "list[Route]" = []


class Shell:
    """A persistent layout that wraps a group of routes — like React Router's
    layout routes or Flutter's ``ShellRoute``.

    **Subclass it** to define the layout (it is App-like: ``State``, methods and
    a ``build()``). Put a single :class:`~workpeg.ui.widgets.Outlet` where the
    routed child should appear::

        class AppShell(Shell):
            open = State(True)
            def toggle(self): self.open = not self.open
            def build(self):
                return Row(Sidebar(self.open, self.toggle), Outlet(),
                           align="stretch")

    **Group routes under it** in a :class:`Router`'s ``routes`` list. With no
    prefix the child paths are absolute; pass a prefix (which may contain a
    ``[param]``) for a shell nested under a dynamic segment::

        class Site(Router):
            routes = [
                Shell(AppShell, [Route("/", Home), Route("/reports", Reports)]),
                Shell(ProjectShell, "/projects/[id]",
                      [Route("/overview", Overview), Route("/members", Members)]),
                Route("/login", Login),          # shell-less
            ]

    The shell renders once and stays mounted: navigating between its child
    routes swaps only the Outlet, so the shell's own widgets never repaint and
    its ``State`` survives. Children read shared data through ``route.<param>``
    and the global ``store``. A dynamic-prefix shell remounts only when its
    captured param changes (e.g. a different ``[id]``).
    """

    def __init__(
        self,
        shell: type,
        prefix: "str | list[Route]" = "",
        routes: "list[Route] | None" = None,
    ) -> None:
        # Two-arg form Shell(Cls, [routes]) has no prefix; three-arg form
        # Shell(Cls, "/prefix", [routes]) nests the group under the prefix.
        if routes is None and isinstance(prefix, list):
            prefix, routes = "", prefix
        self.shell = shell
        self.prefix = prefix
        self.routes = routes or []


class PegApp:
    def __init__(
        self,
        title: str,
        child: BaseWidget,
        *,
        state: State | None = None,
        metadata: dict[str, Any] | None = None,
    ):
        self.title = title
        self.child = child
        self.state = state or State()
        self.metadata = metadata or {}

    def to_schema(self) -> dict[str, Any]:
        return {
            "type": "PegApp",
            "props": {
                "title": self.title,
                "metadata": self.metadata,
            },
            "state": self.state.to_schema(),
            "child": self.child.to_schema(state=self.state),
        }


class Page(BaseWidget):
    widget_type = "Page"

    def __init__(
        self,
        title: str,
        child: BaseWidget,
        *,
        subtitle: str | None = None,
        key: str | None = None,
        metadata: dict[str, Any] | None = None,
    ):
        super().__init__(key=key, metadata=metadata)
        self.title = title
        self.subtitle = subtitle
        self.child = child

    def props(self) -> dict[str, Any]:
        return {
            "title": self.title,
            "subtitle": self.subtitle,
        }

    def children(self):
        return [self.child]
